      name: 'order_status',
      description: 'Get the current status of an order by its ID. Optionally include the chronological history of status changes.',
      inputSchema: {
        type: 'object',
        properties: {
          order_id: { type: 'string', description: 'The order identifier.' },
          include_history: { type: 'boolean', default: false, description: 'Whether to include the chronological history of status changes.' }
